type MessageCatalog = Record<ConsoleLocale, Record<string, Record<string, string>>>;

function flattenMessages(namespaces: Record<string, Record<string, string>>): Map<string, string> {
  return new Map(Object.entries(namespaces).flatMap(([namespace, messages]) =>
    Object.entries(messages).map(([key, message]) => [`${namespace}.${key}`, message]),
  ));
}

function interpolationNames(message: string): string[] {
  return [...message.matchAll(/\{\{(\w+)\}\}/g)].map((match) => match[1]).sort();
}

export function assertConsoleLocaleCompleteness(catalog: MessageCatalog): void {
  const defaultMessages = flattenMessages(catalog["en-US"]);
  for (const locale of consoleLocales) {
    const localeMessages = flattenMessages(catalog[locale]);
    for (const [key, defaultMessage] of defaultMessages) {
      const localeMessage = localeMessages.get(key);
      if (localeMessage === undefined) throw new Error(`locale key missing: ${locale}.${key}`);
      if (JSON.stringify(interpolationNames(localeMessage)) !== JSON.stringify(interpolationNames(defaultMessage))) {
        throw new Error(`locale interpolation mismatch: ${locale}.${key}`);
      }
    }
    for (const key of localeMessages.keys()) {
      if (!defaultMessages.has(key)) throw new Error(`locale key is not registered in en-US: ${locale}.${key}`);
    }
  }
}

assertConsoleLocaleCompleteness(resources);

function toConsoleLocale(value: string | null | undefined): ConsoleLocale | undefined {
  if (value === "en-US" || value === "zh-CN") return value;
  if (value?.toLowerCase().startsWith("en")) return "en-US";
  if (value?.toLowerCase().startsWith("zh")) return "zh-CN";
  return undefined;
}

function readAnonymousLocalePreference(): ConsoleLocale | undefined {
  try {
    return typeof window === "undefined" ? undefined : toConsoleLocale(window.localStorage.getItem(anonymousLocaleStorageKey));
  } catch {
    return undefined;
  }
}

function readBrowserLocalePreference(): ConsoleLocale | undefined {
  if (typeof navigator === "undefined") return undefined;
  return navigator.languages.map(toConsoleLocale).find((locale) => locale !== undefined) ?? toConsoleLocale(navigator.language);
}

export function resolveConsoleLocale(savedUserPreference?: string): ConsoleLocale {
  return toConsoleLocale(savedUserPreference) ?? readAnonymousLocalePreference() ?? readBrowserLocalePreference() ?? "en-US";
}

export function persistAnonymousConsoleLocale(locale: ConsoleLocale) {
  try {
    window.localStorage.setItem(anonymousLocaleStorageKey, locale);
  } catch {
    // Local preference remains optional when storage is unavailable.
  }
}

export function formatConsoleDateTime(value: Date | number, locale: ConsoleLocale, timeZone?: string): string {
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short", timeZone }).format(value);
}

export function formatConsoleNumber(value: number, locale: ConsoleLocale): string {
  return new Intl.NumberFormat(locale).format(value);
}

export function formatConsolePercent(value: number, locale: ConsoleLocale): string {
  return new Intl.NumberFormat(locale, { style: "percent" }).format(value);
}

export function formatConsoleRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, locale: ConsoleLocale): string {
  return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(value, unit);
}

export function formatConsoleUnit(value: number, unit: Intl.NumberFormatOptions["unit"], locale: ConsoleLocale): string {
  return new Intl.NumberFormat(locale, { style: "unit", unit, unitDisplay: "short" }).format(value);
}

