import React, { Component, type ErrorInfo, type MouseEventHandler, type ReactNode } from "react";
import { Link, NavLink } from "react-router";
import { useTranslation } from "react-i18next";
import { LanguageSegmentedControl } from "@oac/ui";

import { consoleI18n, resolveConsoleLocale, type ConsoleLocale } from "../i18n/i18n";
import type { AuthenticatedConsoleSession } from "../session/ConsoleSession";
import styles from "./ConsoleShell.module.css";

export type ConsoleShellContext =
  | { kind: "anonymous" }
  | AuthenticatedConsoleSession;

type ConsoleShellProps = {
  attentionCount: number;
  children: ReactNode;
  context: ConsoleShellContext;
  locale?: ConsoleLocale;
  onLanguageChange?: (locale: ConsoleLocale) => void;
};

type LoginHandoffProps = {
  locale?: ConsoleLocale;
  onLanguageChange?: (locale: ConsoleLocale) => void;
  onSignIn?: MouseEventHandler<HTMLAnchorElement>;
};

type LanguageSwitcherProps = {
  locale: ConsoleLocale;
  onLanguageChange?: (locale: ConsoleLocale) => void;
};

export function LanguageSwitcher({ locale, onLanguageChange }: LanguageSwitcherProps) {
  const { t } = useTranslation();

  return (
    <LanguageSegmentedControl label={t("language")} value={locale} onChange={(nextLocale) => onLanguageChange?.(nextLocale)} />
  );
}

export function LoginHandoff({ locale = resolveConsoleLocale(), onLanguageChange, onSignIn }: LoginHandoffProps) {
  const { t } = useTranslation();
  return (
    <main aria-label={t("entryName")} className={styles.loginHandoff}>
      <LanguageSwitcher locale={locale} onLanguageChange={onLanguageChange} />
      <p className={styles.kicker}>Open Agent Cluster</p>
      <h1>{t("entryName")}</h1>
      <p>{t("loginDescription")}</p>
      <a className={styles.primaryAction} href="/login" onClick={onSignIn}>
        {t("signIn")}
      </a>
      <p className={styles.loginSupport}>{t("loginSupport")}</p>
    </main>
  );
}

export function LoginRoute({ locale = resolveConsoleLocale(), onLanguageChange }: Omit<LoginHandoffProps, "onSignIn">) {
  const { t } = useTranslation();
  return (
    <main aria-label={t("signIn")} className={styles.loginHandoff}>
      <LanguageSwitcher locale={locale} onLanguageChange={onLanguageChange} />
      <p className={styles.kicker}>Open Agent Cluster</p>
      <h1>{t("signIn")}</h1>
      <p>{t("loginRouteDescription")}</p>
      <Link className={styles.secondaryAction} to="/">{t("backToConsole")}</Link>
    </main>
  );
}

type ConsoleSessionStatusProps = {
  kind: "resolving" | "unavailable";
  onRetry?: () => void;
};

export function ConsoleSessionStatus({ kind, onRetry }: ConsoleSessionStatusProps) {
  const { t } = useTranslation();
  const unavailable = kind === "unavailable";
  return (
    <main aria-label={unavailable ? t("sessionUnavailableTitle") : t("sessionResolvingTitle")} className={styles.sessionStatus}>
      <div role={unavailable ? "alert" : "status"}>
        <h1>{t(unavailable ? "sessionUnavailableTitle" : "sessionResolvingTitle")}</h1>
        <p>{t(unavailable ? "sessionUnavailableDescription" : "sessionResolvingDescription")}</p>
        {unavailable && <button className={styles.primaryButton} onClick={onRetry} type="button">{t("tryAgain")}</button>}
      </div>
    </main>
  );
}

export function ConsoleShell({
  attentionCount,
  children,
  context,
  locale = resolveConsoleLocale(),
  onLanguageChange,
}: ConsoleShellProps) {
  const { t } = useTranslation();
  const navigationItems = [
    { href: "/", label: t("overview") },
    { href: "/projects", label: t("projects") },
    { href: "/workflows", label: t("workflows") },
    { href: "/settings", label: t("settings") },
  ];
  if (context.kind === "anonymous") {
    return <LoginHandoff locale={locale} onLanguageChange={onLanguageChange} />;
  }

  return (
    <div className={styles.shell}>
      <header className={styles.header}>
        <NavLink className={styles.brand} to="/" aria-label={t("entryName")}>
          OAC
        </NavLink>
        <div className={styles.scope} aria-label={t("currentScope")}>
          <span className={styles.scopeLabel}>{t("scope")}</span>
          <strong>{context.scope.name}</strong>
        </div>
        <div className={styles.account} aria-label={t("account")}>
          <span>{context.principalName}</span>
          <span aria-hidden="true">·</span>
          <span>{context.scope.id}</span>
          <LanguageSwitcher locale={locale} onLanguageChange={onLanguageChange} />
        </div>
      </header>
      <div className={styles.shellLayout}>
        <nav aria-label={t("navigation")} className={styles.navigation}>
          {navigationItems.map((item) => (
            <NavLink
              className={styles.navigationLink}
              key={item.href}
              to={item.href}
            >
              {item.label}
            </NavLink>
          ))}
          <NavLink
            aria-label={t("attentionCount", { count: attentionCount })}
            className={styles.attentionLink}
            to="/attention"
          >
            {t("attention")} <span aria-hidden="true">{attentionCount}</span>
          </NavLink>
        </nav>
        <main className={styles.workSurface} id="console-content" tabIndex={-1}>
          {children}
        </main>
      </div>
    </div>
  );
}

type ConsoleErrorBoundaryState = {
  hasError: boolean;
};

export class ConsoleErrorBoundary extends Component<{ children: ReactNode }, ConsoleErrorBoundaryState> {
  public state: ConsoleErrorBoundaryState = { hasError: false };

  public static getDerivedStateFromError(): ConsoleErrorBoundaryState {
    return { hasError: true };
  }

  public componentDidCatch(_error: Error, _errorInfo: ErrorInfo) {
    // The shell must not expose error details from an API or a downstream domain surface.
  }

  public render() {
    if (this.state.hasError) {
      return (
          <main aria-label={consoleI18n.t("consoleError")} className={styles.errorFallback}>
          <div role="alert">
            <h1>{consoleI18n.t("errorTitle")}</h1>
            <p>{consoleI18n.t("errorDescription")}</p>
            <code>{consoleI18n.t("errorCode")}</code>
          </div>
        </main>
      );
    }

    return this.props.children;
  }
}
